{"cmd":"cat > /root/output/css/style.css <<'CSS'
:root {
  --bg: #f6f1ea;
  --bg-accent: #fefcf9;
  --ink: #1d1f2a;
  --muted: #6b6f7a;
  --panel: #ffffff;
  --panel-border: rgba(29, 31, 42, 0.12);
  --highlight: #ffb347;
  --shadow: 0 16px 40px rgba(24, 28, 44, 0.12);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Space Grotesk", "Helvetica Neue", Arial, sans-serif;
  color: var(--ink);
  background: radial-gradient(circle at top left, #fff5e6 0%, var(--bg) 40%, #e7ecf7 100%);
}

.app {
  max-width: 1400px;
  margin: 32px auto 48px;
  padding: 0 24px;
}

header {
  margin-bottom: 18px;
}

header h1 {
  margin: 0 0 6px;
  font-size: 28px;
  letter-spacing: -0.02em;
}

header p {
  margin: 0;
  color: var(--muted);
}

.layout {
  display: flex;
  gap: 24px;
  align-items: stretch;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 16px;
  padding: 18px;
  box-shadow: var(--shadow);
}

#bubble-panel {
  flex: 1.1;
  min-width: 420px;
}

#table-panel {
  flex: 0.9;
  min-width: 360px;
  display: flex;
  flex-direction: column;
}

.panel-header {
  font-weight: 600;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

#bubble-chart svg {
  width: 100%;
  height: 600px;
}

.legend text {
  font-size: 12px;
  fill: var(--muted);
}

.nodes circle {
  stroke: rgba(0, 0, 0, 0.08);
  stroke-width: 1px;
  transition: stroke 0.2s ease, opacity 0.2s ease;
}

.nodes text {
  font-size: 11px;
  fill: #1a1c26;
  pointer-events: none;
  font-weight: 600;
}

.node.selected circle {
  stroke: var(--highlight);
  stroke-width: 3px;
}

.node.dimmed {
  opacity: 0.35;
}

.table-wrap {
  overflow: auto;
  border-radius: 12px;
  border: 1px solid rgba(29, 31, 42, 0.08);
  flex: 1;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #f7f5f2;
  text-align: left;
  padding: 10px 12px;
  font-weight: 600;
  border-bottom: 1px solid rgba(29, 31, 42, 0.1);
  z-index: 1;
}

#stock-table tbody td {
  padding: 10px 12px;
  border-bottom: 1px solid rgba(29, 31, 42, 0.06);
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;
}

#stock-table tbody tr:hover {
  background: rgba(255, 179, 71, 0.15);
}

#stock-table tbody tr.selected {
  background: rgba(255, 179, 71, 0.35);
  color: #1c1200;
  font-weight: 600;
}

.tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(255, 255, 255, 0.95);
  border: 1px solid rgba(29, 31, 42, 0.15);
  border-radius: 12px;
  padding: 10px 12px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
  font-size: 12px;
  color: var(--ink);
  opacity: 0;
  transition: opacity 0.15s ease;
}

.tooltip .tt-title {
  font-weight: 700;
  font-size: 14px;
}

.tooltip .tt-name {
  margin-top: 2px;
}

.tooltip .tt-sector {
  margin-top: 6px;
  color: var(--muted);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: 10px;
}

.tooltip svg {
  margin-top: 8px;
}

@media (max-width: 1100px) {
  .layout {
    flex-direction: column;
  }

  #bubble-chart svg {
    height: 520px;
  }
}
CSS"}

{"cmd":"cat > /root/output/js/visualization.js <<'JS'
(() => {
  const width = 720;
  const height = 600;
  const bubbleContainer = d3.select("#bubble-chart");
  const svg = bubbleContainer
    .append("svg")
    .attr("viewBox", `0 0 ${width} ${height}`)
    .attr("preserveAspectRatio", "xMidYMid meet");

  const tooltip = d3
    .select("body")
    .append("div")
    .attr("class", "tooltip");

  const historyCache = new Map();

  const formatCap = (value) => {
    if (!Number.isFinite(value)) return "N/A";
    const abs = Math.abs(value);
    if (abs >= 1e12) return `${(value / 1e12).toFixed(2).replace(/\.00$/, "")}T`;
    if (abs >= 1e9) return `${(value / 1e9).toFixed(2).replace(/\.00$/, "")}B`;
    if (abs >= 1e6) return `${(value / 1e6).toFixed(2).replace(/\.00$/, "")}M`;
    return d3.format(",")(value);
  };

  const loadHistory = (ticker) => {
    if (historyCache.has(ticker)) {
      return Promise.resolve(historyCache.get(ticker));
    }
    const url = `data/indiv-stock/${ticker}.csv`;
    return d3
      .csv(url, (d) => ({
        date: new Date(d.Date),
        close: +d.Close,
      }))
      .then((data) => {
        const clean = data.filter(
          (d) => d.date instanceof Date && !Number.isNaN(d.date) && Number.isFinite(d.close)
        );
        clean.sort((a, b) => a.date - b.date);
        historyCache.set(ticker, clean);
        return clean;
      })
      .catch(() => {
        historyCache.set(ticker, []);
        return [];
      });
  };

  const renderSparkline = (series, color) => {
    const spark = tooltip.select("svg.tt-spark");
    if (spark.empty() || !series.length) return;
    spark.selectAll("*").remove();

    const margin = { top: 4, right: 4, bottom: 4, left: 4 };
    const w = +spark.attr("width") - margin.left - margin.right;
    const h = +spark.attr("height") - margin.top - margin.bottom;

    const trimmed = series.slice(-90);
    const x = d3
      .scaleTime()
      .domain(d3.extent(trimmed, (d) => d.date))
      .range([0, w]);
    const y = d3
      .scaleLinear()
      .domain(d3.extent(trimmed, (d) => d.close))
      .nice()
      .range([h, 0]);

    const line = d3
      .line()
      .x((d) => x(d.date))
      .y((d) => y(d.close));

    const g = spark
      .append("g")
      .attr("transform", `translate(${margin.left},${margin.top})`);

    g.append("path")
      .datum(trimmed)
      .attr("fill", "none")
      .attr("stroke", color)
      .attr("stroke-width", 1.6)
      .attr("d", line);
  };

  const showTooltip = (event, d, color) => {
    if (d.isETF) return;
    tooltip
      .style("opacity", 1)
      .attr("data-ticker", d.ticker)
      .html(
        `<div class="tt-title">${d.ticker}</div>` +
          `<div class="tt-name">${d.name}</div>` +
          `<div class="tt-sector">${d.sector}</div>` +
          `<svg class="tt-spark" width="160" height="50"></svg>`
      );

    const [x, y] = d3.pointer(event, document.body);
    tooltip
      .style("left", `${x + 14}px`)
      .style("top", `${y + 14}px`);

    loadHistory(d.ticker).then((series) => {
      if (tooltip.attr("data-ticker") === d.ticker) {
        renderSparkline(series, color);
      }
    });
  };

  const moveTooltip = (event) => {
    const [x, y] = d3.pointer(event, document.body);
    tooltip
      .style("left", `${x + 14}px`)
      .style("top", `${y + 14}px`);
  };

  const hideTooltip = () => {
    tooltip.style("opacity", 0).attr("data-ticker", "");
  };

  d3.csv("data/stock-descriptions.csv", d3.autoType).then((raw) => {
    const stocks = raw
      .filter((d) => d.ticker)
      .map((d) => ({
        ticker: String(d.ticker).trim(),
        name: d["full name"],
        sector: d.sector || "Other",
        marketCap: Number.isFinite(d.marketCap) ? d.marketCap : NaN,
      }));

    const sectors = Array.from(new Set(stocks.map((d) => d.sector))).sort();
    const palette = sectors.length <= 10 ? d3.schemeTableau10 : d3.schemeSet3;
    const color = d3
      .scaleOrdinal()
      .domain(sectors)
      .range(palette.concat(palette).slice(0, sectors.length));

    const capValues = stocks
      .map((d) => d.marketCap)
      .filter((v) => Number.isFinite(v) && v > 0);
    const minCap = d3.min(capValues);
    const maxCap = d3.max(capValues);
    const rScale = d3
      .scaleSqrt()
      .domain([minCap, maxCap])
      .range([12, 52]);

    const uniformRadius = 15;

    const center = { x: width / 2, y: height / 2 };
    const ring = Math.min(width, height) * 0.22;

    const sectorCenters = new Map();
    sectors.forEach((sector, i) => {
      const angle = (i / sectors.length) * Math.PI * 2;
      sectorCenters.set(sector, {
        x: center.x + ring * Math.cos(angle),
        y: center.y + ring * Math.sin(angle),
      });
    });

    stocks.forEach((d) => {
      d.isETF = !Number.isFinite(d.marketCap) || d.marketCap === 0;
      d.radius = d.isETF ? uniformRadius : rScale(d.marketCap);
      const c = sectorCenters.get(d.sector);
      d.x = c.x + (Math.random() - 0.5) * 40;
      d.y = c.y + (Math.random() - 0.5) * 40;
    });

    const nodeGroup = svg.append("g").attr("class", "nodes");

    const nodes = nodeGroup
      .selectAll("g.node")
      .data(stocks, (d) => d.ticker)
      .enter()
      .append("g")
      .attr("class", "node")
      .attr("data-ticker", (d) => d.ticker)
      .on("mouseover", function (event, d) {
        showTooltip(event, d, color(d.sector));
      })
      .on("mousemove", moveTooltip)
      .on("mouseout", hideTooltip);

    nodes
      .append("circle")
      .attr("r", (d) => d.radius)
      .attr("fill", (d) => color(d.sector));

    nodes
      .append("text")
      .text((d) => d.ticker)
      .attr("text-anchor", "middle")
      .attr("dy", "0.35em");

    const legend = svg.append("g").attr("class", "legend");
    const legendItems = legend
      .selectAll("g")
      .data(sectors)
      .enter()
      .append("g")
      .attr("transform", (d, i) => `translate(16, ${20 + i * 18})`);

    legendItems
      .append("rect")
      .attr("width", 10)
      .attr("height", 10)
      .attr("rx", 3)
      .attr("fill", (d) => color(d));

    legendItems
      .append("text")
      .attr("x", 16)
      .attr("y", 9)
      .text((d) => d);

    const simulation = d3
      .forceSimulation(stocks)
      .force(
        "x",
        d3
          .forceX((d) => sectorCenters.get(d.sector).x)
          .strength(0.22)
      )
      .force(
        "y",
        d3
          .forceY((d) => sectorCenters.get(d.sector).y)
          .strength(0.22)
      )
      .force("collide", d3.forceCollide((d) => d.radius + 2).iterations(2))
      .force("charge", d3.forceManyBody().strength(-6))
      .force("center", d3.forceCenter(center.x, center.y))
      .on("tick", () => {
        nodes.attr("transform", (d) => `translate(${d.x},${d.y})`);
      });

    let selectedTicker = null;

    const tableBody = d3.select("#stock-table tbody");
    const rows = tableBody
      .selectAll("tr")
      .data(stocks, (d) => d.ticker)
      .enter()
      .append("tr")
      .attr("data-ticker", (d) => d.ticker)
      .on("click", (event, d) => {
        setSelected(d.ticker);
      });

    rows
      .append("td")
      .text((d) => d.ticker);
    rows
      .append("td")
      .text((d) => d.name);
    rows
      .append("td")
      .text((d) => d.sector);
    rows
      .append("td")
      .text((d) => formatCap(d.marketCap));

    nodes.on("click", (event, d) => {
      setSelected(d.ticker);
    });

    const setSelected = (ticker) => {
      selectedTicker = selectedTicker === ticker ? null : ticker;
      updateSelection();
    };

    const updateSelection = () => {
      nodes
        .classed("selected", (d) => d.ticker === selectedTicker)
        .classed("dimmed", (d) => selectedTicker && d.ticker !== selectedTicker);
      rows
        .classed("selected", (d) => d.ticker === selectedTicker)
        .classed("dimmed", (d) => selectedTicker && d.ticker !== selectedTicker);
    };

    updateSelection();
  });
})();
JS"}

